import{_ as l,a0 as o,w as d,s as r,I as e,x as a,a1 as t,A as n,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"系統管理員需知的 16 個 iptables 使用技巧 | LCTT x X-CMD","titleTemplate":false,"description":"系統管理員需知的 16 個 iptables 使用技巧 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"系統管理員需知的 16 個 iptables 使用技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"系統管理員需知的 16 個 iptables 使用技巧 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20181001 16 iptables tips and tricks for sysadmins","title":"系統管理員需知的 16 個 iptables 使用技巧","tag":"201810","desc":""},"relativePath":"201810/20181001 16 iptables tips and tricks for sysadmins.md","filePath":"[post].md"}'),h={name:"201810/20181001 16 iptables tips and tricks for sysadmins.md"};function c(b,s,k,g,u,f){const i=o("Link");return d(),r("div",null,[s[30]||(s[30]=e("h1",{id:"系統管理員需知的-16-個-iptables-使用技巧",tabindex:"-1"},[a("系統管理員需知的 16 個 iptables 使用技巧 "),e("a",{class:"header-anchor",href:"#系統管理員需知的-16-個-iptables-使用技巧","aria-label":"Permalink to “系統管理員需知的 16 個 iptables 使用技巧”"},"​")],-1)),s[31]||(s[31]=e("blockquote",null,[e("p",null,"iptables 是一款控制系統進出流量的強大配置工具。")],-1)),s[32]||(s[32]=e("p",null,[e("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/command_line_prompt.png?itok=wbGiJ_yg",alt:""})],-1)),e("p",null,[s[2]||(s[2]=a("現代 Linux 內核帶有一個叫 ",-1)),t(i,{href:"https://en.wikipedia.org/wiki/Netfilter"},{default:n(()=>[...s[0]||(s[0]=[a("Netfilter",-1)])]),_:1}),s[3]||(s[3]=a(" 的數據包過濾框架。Netfilter 提供了允許、丟棄以及修改等操作來控制進出系統的流量數據包。基於 Netfilter 框架的用户層命令列工具 ",-1)),s[4]||(s[4]=e("code",null,"iptables",-1)),s[5]||(s[5]=a(" 提供了強大的防火牆配置功能，允許你添加規則來構建防火牆策略。",-1)),t(i,{href:"https://en.wikipedia.org/wiki/Iptables"},{default:n(()=>[...s[1]||(s[1]=[a("iptables",-1)])]),_:1}),s[6]||(s[6]=a(" 豐富複雜的功能以及其巴洛克式命令語法可能讓人難以駕馭。我們就來探討一下其中的一些功能，提供一些系統管理員解決某些問題需要的使用技巧。",-1))]),s[33]||(s[33]=p(`<h3 id="避免封鎖自己" tabindex="-1">避免封鎖自己 <a class="header-anchor" href="#避免封鎖自己" aria-label="Permalink to “避免封鎖自己”">​</a></h3><p>應用場景：假設你將對公司服務器上的防火牆規則進行修改，你需要避免封鎖你自己以及其他同事的情況（這將會帶來一定時間和金錢的損失，也許一旦發生馬上就有部門打電話找你了）</p><h4 id="技巧-1-開始之前先備份一下-iptables-配置文件。" tabindex="-1">技巧 #1: 開始之前先備份一下 iptables 配置文件。 <a class="header-anchor" href="#技巧-1-開始之前先備份一下-iptables-配置文件。" aria-label="Permalink to “技巧 #1: 開始之前先備份一下 iptables 配置文件。”">​</a></h4><p>用如下命令備份配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/sbin/iptables-save &gt; /root/iptables-works</span></span></code></pre></div><h4 id="技巧-2-更妥當的做法-給文件加上時間戳。" tabindex="-1">技巧 #2: 更妥當的做法，給文件加上時間戳。 <a class="header-anchor" href="#技巧-2-更妥當的做法-給文件加上時間戳。" aria-label="Permalink to “技巧 #2: 更妥當的做法，給文件加上時間戳。”">​</a></h4><p>用如下命令加時間戳：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/sbin/iptables-save &gt; /root/iptables-works-\`date +%F\`</span></span></code></pre></div><p>然後你就可以生成如下名字的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/root/iptables-works-2018-09-11</span></span></code></pre></div><p>這樣萬一使得系統不工作了，你也可以很快的利用備份文件恢復原狀：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/sbin/iptables-restore &lt; /root/iptables-works-2018-09-11</span></span></code></pre></div><h4 id="技巧-3-每次創建-iptables-配置文件副本時-都創建一個指向最新的文件的鏈接。" tabindex="-1">技巧 #3: 每次創建 iptables 配置文件副本時，都創建一個指向最新的文件的鏈接。 <a class="header-anchor" href="#技巧-3-每次創建-iptables-配置文件副本時-都創建一個指向最新的文件的鏈接。" aria-label="Permalink to “技巧 #3: 每次創建 iptables 配置文件副本時，都創建一個指向最新的文件的鏈接。”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ln –s /root/iptables-works-\`date +%F\` /root/iptables-works-latest</span></span></code></pre></div><h4 id="技巧-4-將特定規則放在策略頂部-底部放置通用規則。" tabindex="-1">技巧 #4: 將特定規則放在策略頂部，底部放置通用規則。 <a class="header-anchor" href="#技巧-4-將特定規則放在策略頂部-底部放置通用規則。" aria-label="Permalink to “技巧 #4: 將特定規則放在策略頂部，底部放置通用規則。”">​</a></h4><p>避免在策略頂部使用如下的一些通用規則：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>iptables -A INPUT -p tcp --dport 22 -j DROP</span></span></code></pre></div><p>你在規則中指定的條件越多，封鎖自己的可能性就越小。不要使用上面非常通用的規則，而是使用如下的規則：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>iptables -A INPUT -p tcp --dport 22 –s 10.0.0.0/8 –d 192.168.100.101 -j DROP</span></span></code></pre></div><p>此規則表示在 <code>INPUT</code> 鏈尾追加一條新規則，將源地址為 <code>10.0.0.0/8</code>、 目的地址是 <code>192.168.100.101</code>、目的端口號是 <code>22</code> （<code>--dport 22</code> ） 的 TCP（<code>-p tcp</code> ）數據包通通丟棄掉。</p><p>還有很多方法可以設置更具體的規則。例如，使用 <code>-i eth0</code> 將會限制這條規則作用於 <code>eth0</code> 網卡，對 <code>eth1</code> 網卡則不生效。</p><h4 id="技巧-5-在策略規則頂部將你的-ip-列入白名單。" tabindex="-1">技巧 #5: 在策略規則頂部將你的 IP 列入白名單。 <a class="header-anchor" href="#技巧-5-在策略規則頂部將你的-ip-列入白名單。" aria-label="Permalink to “技巧 #5: 在策略規則頂部將你的 IP 列入白名單。”">​</a></h4><p>這是一個有效地避免封鎖自己的設置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>iptables -I INPUT -s &lt;your IP&gt; -j ACCEPT</span></span></code></pre></div><p>你需要將該規則添加到策略首位置。<code>-I</code> 表示則策略首部插入規則，<code>-A</code> 表示在策略尾部追加規則。</p><h4 id="技巧-6-理解現有策略中的所有規則。" tabindex="-1">技巧 #6: 理解現有策略中的所有規則。 <a class="header-anchor" href="#技巧-6-理解現有策略中的所有規則。" aria-label="Permalink to “技巧 #6: 理解現有策略中的所有規則。”">​</a></h4><p>不犯錯就已經成功了一半。如果你瞭解 iptables 策略背後的工作原理，使用起來更為得心應手。如果有必要，可以繪製流程圖來理清數據包的走向。還要記住：策略的預期效果和實際效果可能完全是兩回事。</p><h3 id="設置防火牆策略" tabindex="-1">設置防火牆策略 <a class="header-anchor" href="#設置防火牆策略" aria-label="Permalink to “設置防火牆策略”">​</a></h3><p>應用場景：你希望給工作站配置具有限制性策略的防火牆。</p><h4 id="技巧-1-設置默認規則為丟棄" tabindex="-1">技巧 #1: 設置默認規則為丟棄 <a class="header-anchor" href="#技巧-1-設置默認規則為丟棄" aria-label="Permalink to “技巧 #1: 設置默認規則為丟棄”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Set a default policy of DROP</span></span>
<span class="line"><span>*filter</span></span>
<span class="line"><span>:INPUT DROP [0:0]</span></span>
<span class="line"><span>:FORWARD DROP [0:0]</span></span>
<span class="line"><span>:OUTPUT DROP [0:0]</span></span></code></pre></div><h4 id="技巧-2-將用户完成工作所需的最少量服務設置為允許" tabindex="-1">技巧 #2: 將用户完成工作所需的最少量服務設置為允許 <a class="header-anchor" href="#技巧-2-將用户完成工作所需的最少量服務設置為允許" aria-label="Permalink to “技巧 #2: 將用户完成工作所需的最少量服務設置為允許”">​</a></h4><p>該策略需要允許工作站能通過 DHCP（<code>-p udp --dport 67:68 -sport 67:68</code>）來獲取 IP 地址、子網掩碼以及其他一些信息。對於遠程操作，需要允許 SSH 服務（<code>-dport 22</code>），郵件服務（<code>--dport 25</code>），DNS 服務（<code>--dport 53</code>），ping 功能（<code>-p icmp</code>），NTP 服務（<code>--dport 123 --sport 123</code>）以及 HTTP 服務（<code>-dport 80</code>）和 HTTPS 服務（<code>--dport 443</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Set a default policy of DROP</span></span>
<span class="line"><span>*filter</span></span>
<span class="line"><span>:INPUT DROP [0:0]</span></span>
<span class="line"><span>:FORWARD DROP [0:0]</span></span>
<span class="line"><span>:OUTPUT DROP [0:0]</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Accept any related or established connections</span></span>
<span class="line"><span>-I INPUT  1 -m state --state RELATED,ESTABLISHED -j ACCEPT</span></span>
<span class="line"><span>-I OUTPUT 1 -m state --state RELATED,ESTABLISHED -j ACCEPT</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Allow all traffic on the loopback interface</span></span>
<span class="line"><span>-A INPUT -i lo -j ACCEPT</span></span>
<span class="line"><span>-A OUTPUT -o lo -j ACCEPT</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Allow outbound DHCP request</span></span>
<span class="line"><span>-A OUTPUT –o eth0 -p udp --dport 67:68 --sport 67:68 -j ACCEPT</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Allow inbound SSH</span></span>
<span class="line"><span>-A INPUT -i eth0 -p tcp -m tcp --dport 22 -m state --state NEW  -j ACCEPT</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Allow outbound email</span></span>
<span class="line"><span>-A OUTPUT -i eth0 -p tcp -m tcp --dport 25 -m state --state NEW  -j ACCEPT</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Outbound DNS lookups</span></span>
<span class="line"><span>-A OUTPUT -o eth0 -p udp -m udp --dport 53 -j ACCEPT</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Outbound PING requests</span></span>
<span class="line"><span>-A OUTPUT –o eth0 -p icmp -j ACCEPT</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Outbound Network Time Protocol (NTP) requests</span></span>
<span class="line"><span>-A OUTPUT –o eth0 -p udp --dport 123 --sport 123 -j ACCEPT</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Outbound HTTP</span></span>
<span class="line"><span>-A OUTPUT -o eth0 -p tcp -m tcp --dport 80 -m state --state NEW -j ACCEPT</span></span>
<span class="line"><span>-A OUTPUT -o eth0 -p tcp -m tcp --dport 443 -m state --state NEW -j ACCEPT</span></span>
<span class="line"><span></span></span>
<span class="line"><span>COMMIT</span></span></code></pre></div><h3 id="限制-ip-地址範圍" tabindex="-1">限制 IP 地址範圍 <a class="header-anchor" href="#限制-ip-地址範圍" aria-label="Permalink to “限制 IP 地址範圍”">​</a></h3><p>應用場景：貴公司的 CEO 認為員工在 Facebook 上花費過多的時間，需要採取一些限制措施。CEO 命令下達給 CIO，CIO 命令 CISO，最終任務由你來執行。你決定阻止一切到 Facebook 的訪問連接。首先你使用 <code>host</code> 或者 <code>whois</code> 命令來獲取 Facebook 的 IP 地址。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>host -t a www.facebook.com</span></span>
<span class="line"><span>www.facebook.com is an alias for star.c10r.facebook.com.</span></span>
<span class="line"><span>star.c10r.facebook.com has address 31.13.65.17</span></span>
<span class="line"><span>whois 31.13.65.17 | grep inetnum</span></span>
<span class="line"><span>inetnum:        31.13.64.0 - 31.13.127.255</span></span></code></pre></div>`,37)),e("p",null,[s[8]||(s[8]=a("然後使用 ",-1)),t(i,{href:"http://www.ipaddressguide.com/cidr"},{default:n(()=>[...s[7]||(s[7]=[a("CIDR 到 IPv4 轉換",-1)])]),_:1}),s[9]||(s[9]=a(" 頁面來將其轉換為 CIDR 表示法。然後你得到 ",-1)),s[10]||(s[10]=e("code",null,"31.13.64.0/18",-1)),s[11]||(s[11]=a(" 的地址。輸入以下命令來阻止對 Facebook 的訪問：",-1))]),s[34]||(s[34]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>iptables -A OUTPUT -p tcp -i eth0 –o eth1 –d 31.13.64.0/18 -j DROP</span></span></code></pre></div><h3 id="按時間規定做限制-場景1" tabindex="-1">按時間規定做限制 - 場景1 <a class="header-anchor" href="#按時間規定做限制-場景1" aria-label="Permalink to “按時間規定做限制 - 場景1”">​</a></h3><p>應用場景：公司員工強烈反對限制一切對 Facebook 的訪問，這導致了 CEO 放寬了要求（考慮到員工的反對以及他的助理提醒説她負責更新他的 Facebook 頁面）。然後 CEO 決定允許在午餐時間訪問 Facebook（中午 12 點到下午 1 點之間）。假設默認規則是丟棄，使用 iptables 的時間功能便可以實現。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>iptables –A OUTPUT -p tcp -m multiport --dport http,https -i eth0 -o eth1 -m time --timestart 12:00 –timestop 13:00 –d 31.13.64.0/18 -j ACCEPT</span></span></code></pre></div><p>該命令中指定在中午12點（<code>--timestart 12:00</code>）到下午 1 點（<code>--timestop 13:00</code>）之間允許（<code>-j ACCEPT</code>）到 Facebook.com （<code>-d [31.13.64.0/18][5]</code>）的 http 以及 https （<code>-m multiport --dport http,https</code>）的訪問。</p><h3 id="按時間規定做限制-場景2" tabindex="-1">按時間規定做限制 - 場景2 <a class="header-anchor" href="#按時間規定做限制-場景2" aria-label="Permalink to “按時間規定做限制 - 場景2”">​</a></h3><p>應用場景：在計劃系統維護期間，你需要設置凌晨 2 點到 3 點之間拒絕所有的 TCP 和 UDP 訪問，這樣維護任務就不會受到干擾。使用兩個 iptables 規則可實現：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>iptables -A INPUT -p tcp -m time --timestart 02:00 --timestop 03:00 -j DROP</span></span>
<span class="line"><span>iptables -A INPUT -p udp -m time --timestart 02:00 --timestop 03:00 -j DROP</span></span></code></pre></div><p>該規則禁止（<code>-j DROP</code>）在凌晨2點（<code>--timestart 02:00</code>）到凌晨3點（<code>--timestop 03:00</code>）之間的 TCP 和 UDP （<code>-p tcp and -p udp</code>）的數據進入（<code>-A INPUT</code>）訪問。</p><h3 id="限制連接數量" tabindex="-1">限制連接數量 <a class="header-anchor" href="#限制連接數量" aria-label="Permalink to “限制連接數量”">​</a></h3><p>應用場景：你的 web 服務器有可能受到來自世界各地的 DoS 攻擊，為了避免這些攻擊，你可以限制單個 IP 地址到你的 web 服務器創建連接的數量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>iptables –A INPUT –p tcp –syn -m multiport -–dport http,https –m connlimit -–connlimit-above 20 –j REJECT -–reject-with-tcp-reset</span></span></code></pre></div><p>分析一下上面的命令。如果單個主機在一分鐘之內新建立（<code>-p tcp -syn</code>）超過 20 個（<code>-connlimit-above 20</code>）到你的 web 服務器（<code>--dport http,https</code>）的連接，服務器將拒絕（<code>-j REJECT</code>）建立新的連接，然後通知對方新建連接被拒絕（<code>--reject-with-tcp-reset</code>）。</p><h3 id="監控-iptables-規則" tabindex="-1">監控 iptables 規則 <a class="header-anchor" href="#監控-iptables-規則" aria-label="Permalink to “監控 iptables 規則”">​</a></h3><p>應用場景：由於數據包會遍歷鏈中的規則，iptables 遵循 “首次匹配獲勝” 的原則，因此經常匹配的規則應該靠近策略的頂部，而不太頻繁匹配的規則應該接近底部。 你怎麼知道哪些規則使用最多或最少，可以在頂部或底部附近監控？</p><h4 id="技巧-1-查看規則被訪問了多少次" tabindex="-1">技巧 #1: 查看規則被訪問了多少次 <a class="header-anchor" href="#技巧-1-查看規則被訪問了多少次" aria-label="Permalink to “技巧 #1: 查看規則被訪問了多少次”">​</a></h4><p>使用命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>iptables -L -v -n –line-numbers</span></span></code></pre></div><p>用 <code>-L</code> 選項列出鏈中的所有規則。因為沒有指定具體哪條鏈，所有鏈規則都會被輸出，使用 <code>-v</code> 選項顯示詳細信息，<code>-n</code> 選項則顯示數字格式的數據包和字節計數器，每個規則開頭的數值表示該規則在鏈中的位置。</p><p>根據數據包和字節計數的結果，你可以將訪問頻率最高的規則放到頂部，將訪問頻率最低的規則放到底部。</p><h4 id="技巧-2-刪除不必要的規則" tabindex="-1">技巧 #2: 刪除不必要的規則 <a class="header-anchor" href="#技巧-2-刪除不必要的規則" aria-label="Permalink to “技巧 #2: 刪除不必要的規則”">​</a></h4><p>哪條規則從來沒有被訪問過？這些可以被清除掉。用如下命令查看：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>iptables -nvL | grep -v &quot;0     0&quot;</span></span></code></pre></div><p>注意：兩個數字 0 之間不是 Tab 鍵，而是 <strong>5</strong> 個空格。</p><h4 id="技巧-3-監控正在發生什麼" tabindex="-1">技巧 #3: 監控正在發生什麼 <a class="header-anchor" href="#技巧-3-監控正在發生什麼" aria-label="Permalink to “技巧 #3: 監控正在發生什麼”">​</a></h4><p>可能你也想像使用 <code>top</code> 命令一樣來實時監控 iptables 的情況。使用如下命令來動態監視 iptables 中的活動，並僅顯示正在遍歷的規則：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>watch --interval=5 &#39;iptables -nvL | grep -v &quot;0     0&quot;&#39;</span></span></code></pre></div><p><code>watch</code> 命令通過參數 <code>iptables -nvL | grep -v “0 0“</code> 每隔 5 秒輸出 iptables 的動態。這條命令允許你查看數據包和字節計數的變化。</p><h3 id="輸出日誌" tabindex="-1">輸出日誌 <a class="header-anchor" href="#輸出日誌" aria-label="Permalink to “輸出日誌”">​</a></h3><p>應用場景：經理覺得你這個防火牆員工的工作質量槓槓的，但如果能有網絡流量活動日誌最好了。有時候這比寫一份有關工作的報告更有效。</p>`,30)),e("p",null,[s[13]||(s[13]=a("使用工具 ",-1)),t(i,{href:"http://fwlogwatch.inside-security.de/"},{default:n(()=>[...s[12]||(s[12]=[a("FWLogwatch",-1)])]),_:1}),s[14]||(s[14]=a(" 基於 iptables 防火牆記錄來生成日誌報告。FWLogwatch 工具支持很多形式的報告並且也提供了很多分析功能。它生成的日誌以及月報告使得管理員可以節省大量時間並且還更好地管理網絡，甚至減少未被注意的潛在攻擊。",-1))]),s[35]||(s[35]=e("p",null,"這裏是一個 FWLogwatch 生成的報告示例：",-1)),s[36]||(s[36]=e("p",null,[e("img",{src:"https://opensource.com/sites/default/files/uploads/fwlogwatch.png",alt:""})],-1)),s[37]||(s[37]=e("h3",{id:"不要滿足於允許和丟棄規則",tabindex:"-1"},[a("不要滿足於允許和丟棄規則 "),e("a",{class:"header-anchor",href:"#不要滿足於允許和丟棄規則","aria-label":"Permalink to “不要滿足於允許和丟棄規則”"},"​")],-1)),s[38]||(s[38]=e("p",null,"本文中已經涵蓋了 iptables 的很多方面，從避免封鎖自己、配置 iptables 防火牆以及監控 iptables 中的活動等等方面介紹了 iptables。你可以從這裏開始探索 iptables 甚至獲取更多的使用技巧。",-1)),s[39]||(s[39]=e("hr",null,null,-1)),e("p",null,[s[16]||(s[16]=a("via: ",-1)),t(i,{href:"https://opensource.com/article/18/10/iptables-tips-and-tricks"},{default:n(()=>[...s[15]||(s[15]=[a("https://opensource.com/article/18/10/iptables-tips-and-tricks",-1)])]),_:1})]),e("p",null,[s[21]||(s[21]=a("作者：",-1)),t(i,{href:"https://opensource.com/users/greptile"},{default:n(()=>[...s[17]||(s[17]=[a("Gary Smith",-1)])]),_:1}),s[22]||(s[22]=a(" 選題：",-1)),t(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[18]||(s[18]=[a("lujun9972",-1)])]),_:1}),s[23]||(s[23]=a(" 譯者：",-1)),t(i,{href:"https://github.com/jrglinux"},{default:n(()=>[...s[19]||(s[19]=[a("jrg",-1)])]),_:1}),s[24]||(s[24]=a(" 校對：",-1)),t(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[20]||(s[20]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[27]||(s[27]=a("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[25]||(s[25]=[a("LCTT",-1)])]),_:1}),s[28]||(s[28]=a(" 原創編譯，",-1)),t(i,{href:"https://linux.cn/"},{default:n(()=>[...s[26]||(s[26]=[a("Linux中國",-1)])]),_:1}),s[29]||(s[29]=a(" 榮譽推出",-1))])])}const C=l(h,[["render",c]]);export{T as __pageData,C as default};
